"""Improved PII redactor focusing on SSN detection."""
import re

PATTERNS = [
    ("EMAIL", re.compile(r"[\w.]+@[\w]+\.\w+")),
    ("PHONE", re.compile(r"\d{3}-\d{3}-\d{4}")),
    ("SSN", re.compile(
        r"(?i)(?:ssn|social security number|social security)[:\s]*\b(\d{3}[-\s]?\d{2}[-\s]?\d{4}|\d{9})\b"
    )),
    ("CREDIT_CARD", re.compile(r"\b\d{16}\b")),
]


def find_pii(text):
    """Return a list of (start, end, label) spans that contain PII."""
    spans = []
    for label, pattern in PATTERNS:
        for m in pattern.finditer(text):
            # If the pattern has a capture group (like SSN with context), use the group span
            if m.groups():
                start, end = m.span(1)
            else:
                start, end = m.span()
            spans.append((start, end, label))
    return spans
